(function(root){
'use strict';
// Every option contains the exact line the player sends and its authored answer.
const C=(say,reply,trust=0,interest=0,flag=null,path=null)=>({say,reply,trust,interest,flag,path});
const B=(text,...choices)=>({text,choices});
const S=(title,place,close,...beats)=>({title,place,close,beats});
const stories={};
stories.alex=[
S('The film nobody liked','Tuesday’s film poll','Alex: “I should get back to this book. Good talking to you. See you in the film arguments.”',
 B('Hi—Alex, from the film thread. Were you defending the terrible detective film, or was that a joke? I couldn’t tell.',
 C('Defending it. The dog solved the crime. What more do you need?','The dog did carry the final act. I’ll give you that.',1),C('Mostly a joke. But I had a good time watching it.','Same. A bad film with good company counts.',1),C('I haven’t seen it. I voted because of the poster.','An extremely honest voter. The poster is better than the film.'),C('I’m not much of a film person, honestly.','Fair. I coordinate screenings at the library, so I forget other hobbies exist.'),C('I’d defend almost anything to start a conversation with you.','That’s quite an opening for someone with strong opinions about a dog.',0,1)),
 B('I put it on at our library screening. Six people came. One brought a notebook. I’m worried there’s going to be a review.',
 C('What was in the notebook?','I didn’t ask. Too afraid. It could just have been a shopping list.',1),C('Six people sounds like a good evening to me.','It was, actually. Everyone stayed to argue afterwards.',1,0,'small_group'),C('I’d need more people to feel like a proper event.','Really? I relax more when it’s small. Easier to hear everyone.'),C('You could quote the worst review on the next poster.','“An evening that definitely occurred.” I can work with that.',1),C('Sounds like nobody wanted to go.','We’re a small library. It mattered to the people who came.',-2)),
 B('What do you usually do when you finish work? I ask people this, then remember my answer is often “laundry.”',
 C('Usually make dinner and call someone.','That sounds good. I cook better if I have someone to talk to.',1,0,'company'),C('I need an hour where nobody needs anything.','I get that. I sometimes walk the long way home for exactly that reason.',1,0,'quiet'),C('Go out, if I can persuade a friend.','I admire the energy. I make very optimistic plans at lunchtime.'),C('A game, a podcast, whatever lets me switch off.','Useful answer. I’m collecting alternatives to scrolling beside a pile of laundry.'),C('Are you asking because you want to join me?','Mostly curiosity. We’ve exchanged about five messages. But I’ll remember the invitation.',0,1)),
 B('I’m making a list for the next screening. Do I trust you with one recommendation?',
 C('A comedy. People should leave in a better mood.','Comedy goes on the list. No promises about the mood.',1,0,'comedy'),C('Something strange enough to argue about afterwards.','That sounds more like our crowd. I’ll find something odd.',1,0,'strange_film'),C('A documentary. I like leaving with something new to think about.','Good idea. I know one about a spectacularly unsuccessful choir.',1,0,'documentary'),C('Surprise me. I’ll try to catch the next one.','I’ll post the date in the group. No ticket required.',0,0,'attend'),C('I’d rather just hear whether the notebook person returns.','You’ll be the first to know if I get reviewed.'))),
S('A small success','A follow-up a few days later','Alex: “Dad’s calling. He wants me to identify a noise his fridge is making. Catch you later.”',
 B(({r})=>r.flags.includes('comedy')?'We went with a comedy. Seven people this time. Nobody left, which I’m counting as critical acclaim.':r.flags.includes('documentary')?'I tried that choir documentary. One person knew somebody in it. This city is smaller than I thought.':'The next screening happened. Notebook person returned. They were doing a crossword. I’ve been worried about a crossword.',
 C('A crossword during your film? Brutal.','Apparently the film was helping them concentrate. Somehow.',1),C('How did you feel about the evening?','Relieved. Then immediately worried about the next one.'),C('Glad it went well. Work’s been taking over here.','Ah, one of those weeks. No need to reply in real time.'),C('I wish I’d been there to see your face.','I probably looked very important with a box of biscuits.',0,1),C('Seven still isn’t many.','We’re building it slowly. I’m pleased with seven.',-1)),
 B('Someone stayed behind to help stack chairs. It made a bigger difference than the compliments. Is that a strange thing to remember?',
 C('No. They noticed you were still working.','Exactly. I didn’t have to make a project of asking.',1),C('I’d rather someone asked what help I actually wanted.','Fair point. Uninvited “help” can become another job.',1),C('I mostly remember whether we laughed.','That matters too. The chair-stacking was not especially hilarious.'),C('I’d carry the chairs. You can supervise.','You’re volunteering for a very unglamorous evening.',0,1),C('You shouldn’t expect people to help with your job.','I didn’t expect it. That’s why I appreciated it.',-1)),
 B('I’ve got Saturday free after taking my dad to an appointment. Debating a walk or doing absolutely nothing.',
 C('Absolutely nothing sounds underrated.','You’re a bad influence on my to-do list. Thank you.',1),C('Go for the walk. Even a short one.','Probably sensible. I can turn round if it becomes an expedition.'),C('Is your dad okay? You don’t have to get into it.','Mostly. Ongoing stuff. I’m his transport, not his doctor.',1,0,'asked_dad'),C('I’d be up for trading walking playlists.','That’s a manageable Saturday project. I can do that.',1,0,'playlist'),C('You look after him every weekend? That sounds like a lot.','Not every weekend. But it does take some planning.')),
 B('Before I disappear: are you generally around in the evenings, or am I catching you at bad times?',
 C('Evenings are easiest. I’ll reply when I can.','Same here. No instant-reply contract.',1,0,'evenings'),C('My phone stays away during work. Quiet doesn’t mean anything.','Good to know. I’ll leave messages for later.',1,0,'quiet_phone'),C('I like quick back-and-forth, when we’re both free.','Me too. Less like leaving little notes in a cupboard.'),C('Ask if I’m free first, if it’s a proper conversation.','Can do. “Free for a bit?” is easier than guessing.',1,0,'ask_first'),C('You don’t need my timetable.','I wasn’t asking for one. Just checking I wasn’t interrupting.',-1))),
S('A missed signal','An evening after work','Alex: “I’m going to eat before I become impossible. Speak another day.”',
 B(({r})=>r.flags.includes('ask_first')?'Free for a bit? Something mildly embarrassing happened at work. If not, it’ll keep.':r.flags.includes('quiet_phone')?'Leaving this for after work, as agreed: I accidentally sent the entire library mailing list an unfinished poster.':'Have you got ten minutes? I sent an unfinished poster to our entire mailing list. It just says “EVENT HERE.”',
 C('I’m around. Please tell me “EVENT HERE” got a booking.','Two enquiries. Apparently mystery works.',1),C('I’ve only got a few minutes, but yes.','Short version: I am now the events person with no event.',1,0,'short_chat'),C('That would ruin my entire afternoon.','It nearly did. A colleague put it on the wall, which helped somehow.'),C('I’d go to EVENT HERE with you.','I’m afraid the dress code is “CLOTHES.”',0,1),C('How do you make a mistake like that?','By opening the wrong attachment. It wasn’t my finest moment.',-2)),
 B('A friend suggested I laugh it off online. I don’t really want strangers joining in. I’m fine being teased by people I know.',
 C('Private joke and public joke are different things.','Yes. I couldn’t quite explain why it bothered me.',1,0,'privacy'),C('I’d post it, but I can see why you wouldn’t.','That’s fair. You might have a thicker skin than me.'),C('Just don’t post it. You don’t owe anyone content.','Putting that on a mug. Privately.',1),C('Would you let me tease you about it in person?','Possibly. There’s an application process.',0,1),C('You’re taking a harmless joke too seriously.','It’s still mine to decide whether I share it.',-2,0,'dismissed')),
 B(({r})=>r.flags.includes('short_chat')?'You said a few minutes. I’ve probably used them. Are you okay for one more question?':'Enough about my poster crisis. How’s your week actually been?',
 C('Fine, mostly. Nothing dramatic to report.','Honestly, a non-dramatic week is a good week.'),C('Busy. I said yes to too many things.','I do that. Future me is apparently much more energetic.',1),C('A little lonely, if I’m honest.','I’m sorry. I’ve had those weeks too. Nice talking to someone without having to make an occasion of it.',1),C('Better since we started talking.','That’s nice to hear. I’ve been enjoying it too.',0,1),C('I’m not ready to talk about that.','No problem. We can keep it light.',1)),
 B('There’s a book sale next week. I’ll be there working, so it’s not really a date invitation. But you might like it.',
 C('Send the details. I might come with a friend.','Will do. Bring a bag; people get ambitious.',1,0,'book_sale'),C('I’d rather meet when you aren’t working.','That would be easier. Let’s find something once this is over.',1,1,'date_interest'),C('Book sales aren’t really my thing.','Fair. I won’t hold you hostage among old atlases.'),C('I’m happy just chatting for now.','Okay. No rush.',1,0,'slow'),C('If I go, you need to make time for me.','I’ll be working. I can’t promise you my attention all afternoon.',-2))),
S('Making room','A proper plan','Alex: “Saturday at the corner café, then. I’ll send the table number when I get there.”',
 B(({r})=>r.flags.includes('dismissed')?'Before we make any plans: that comment about me taking things too seriously stayed with me a bit.':r.flags.includes('playlist')?'Your playlist got me through a very long bus ride. I’ve got a return recommendation. But first—coffee?':'The book sale is over. I can now speak about things other than cardboard boxes. Would you still fancy coffee?',
 C('I’d like that. Something simple.','Simple sounds excellent.',1,1,'coffee_yes'),C('Coffee would be nice, as friends.','Thanks for saying. That works for me.',1,0,'friends', 'friends'),C('Thanks for being direct with me. I’d like to meet.',({r})=>r.flags.includes('dismissed')?'Thanks. I wanted to say it rather than quietly stay annoyed.':'Me too. Let’s find an afternoon.',2,0,'repair'),C('I’m interested, but I take a while to warm up.','That’s fine. One coffee doesn’t need to settle anything.',1,0,'slow'),C('Only if you promise not to be so sensitive.','That makes me less interested in meeting, honestly.',-3)),
 B('I can do Saturday afternoon. I need to pick Dad up at five, so it would be an hour or so.',
 C('An hour works. Let’s do three.','Three it is. Plenty of time to decide whether we hate the coffee.',1),C('Could we pick a day when you’re less rushed?','I’m not rushed, but we could make it half two. That gives us longer.',1,0,'early_meet'),C('I worry I’d always fit around your family.','Sometimes it will affect plans. Not always. I’d rather say that now.',0,0,'family_concern'),C('I like that you make time for him.','He’s done plenty of driving for me. I owe him a few lifts.',1),C('Ask someone else to do it. I should come first.','We haven’t met yet. I’m not cancelling on him to prove something.',-3)),
 B('What should I expect? I’m much less polished in person than these beautifully edited messages suggest.',
 C('Someone who also rewrites “sounds good” three times.','Oh, excellent. We can both take ages to order.',1),C('I’m quiet for the first few minutes.','Good to know. I won’t assume you’re bored.',1,0,'shy'),C('I talk too much when I’m nervous.','I’ll keep you away from the library microphone.'),C('Probably some flirting. Fair warning.','Warning received. I reserve the right to be awkward about it.',0,1),C('Please don’t build it up. It’s just coffee.','Fair enough. Coffee, no orchestral score.')),
 B('One last thing: if one of us isn’t feeling it, I’d rather we just say so afterwards. No elaborate disappearing act.',
 C('Agreed. We can be straightforward.','Good. That’s all I meant.',1),C('I might need a day to figure out what I think.','A day is fine. I’m not handing out feedback forms.',1),C('I’d prefer to keep this friendly from the start.','Okay. Friendly coffee it is.',1,0,'friends','friends'),C('I’m hoping we’ll want a second coffee.','Me too, if the first one goes well.',0,1),C('You’re already planning what happens if it goes badly.','I’m trying to make it less awkward, not predict disaster.',-1))),
S('The chair by the window','The corner café','Alex puts her cup down. “I need to get going. I’m glad we did this.” Outside, you both pause before choosing which way to walk.',
 B('“Hi. Alex. I nearly waved at the person behind you.” She moves her bag off the other chair. “Did you find it okay?”',
 C('Eventually. I walked straight past the enormous sign.','“Good. I’m not the only one.”',1),C('Yes. It’s good to finally meet you.','“You too.” She relaxes a little.',1),C('You’re different from how I imagined.','“Better opening than pretending you didn’t imagine anything.”'),C('I’m a little nervous. Give me a minute.','“Take two. I’ve had ten and I’m still nervous.”',1),C('You look lovely.','“Thank you.” She smiles, then looks down at her coffee.',0,1)),
 B(({r})=>r.flags.includes('small_group')?'“You said you like small gatherings. I think this place is about my limit when it gets busy.”':'“I ordered early. Hope you don’t mind. I got here with far too much time to spare.”',
 C('I like arriving early too. Less rushing.','“Exactly. Then I spend the extra time worrying about a different thing.”',1),C('I’m usually the person running round the corner.','“Useful warning. I’ll bring a book.”'),C('What did you order?','“Flat white. I wanted cake, but felt odd beginning without you.”'),C('We could share some cake.','“I was hoping you’d say that.”',1,1),C('You should have waited.','“For a coffee? I didn’t realise that mattered to you.”',-1)),
 B('The conversation drifts to her work. Alex starts telling you about a child who asked whether librarians live in the library, then stops. “Am I talking too much?”',
 C('No. I want to hear the answer.','“I said only the very senior ones. His mum looked horrified.”',1),C('A little. I’d like to tell you something too.','“Sorry. Yes. Your turn.” She puts her phone away.',1),C('I like hearing you talk about something you enjoy.','“I do like it. Even the cardboard-box part.”',1,1),C('Work talk isn’t really my favourite first-date topic.','“Fair. Let’s retire the library for the afternoon.”'),C('Yes. I thought we were here to talk about us.','“There isn’t much of an ‘us’ yet. I’m trying to get to know you.”',-2)),
 B('Her phone lights up with a message from her dad. She checks the time. “I should leave in ten. Would you want to do this again?”',
 C('Yes. I’d like another date.','“I’d like that too.” She takes out her calendar.',1,2,'second_date','romantic'),C('I’d like to see you again, as friends.','“Okay. I enjoyed the afternoon.”',1,0,'friends','friends'),C('I’m not sure about the spark. Can I sleep on it?','“Yeah. Let me know when you’ve had time.”',1,0,'unsure'),C('I enjoyed talking, but I don’t want another date.','“Thanks for being direct. I’m glad we met anyway.”',0,0,'end_romance','friends'),C('If you leave now, I won’t be waiting.','“Then I think we’re done.” She picks up her bag.',-5,0,'end_romance','ended')))
];
stories.ben=[
S('Somewhere still open','A late food recommendation','Ben: “Right, back to closing. Hope you find dinner. Tell me if the place is terrible so I can deny everything.”',
 B('Hi, Ben here. Saw your late-food question. The place beside the station serves until eleven. Avoid the chips. Everything else is good.',
 C('That’s a very specific warning. What happened?','Soggy chips after a twelve-hour shift. I remember betrayal.',1),C('Perfect. I’m starving. Thank you.','Happy to help. Order before they start stacking chairs.'),C('I might just make something at home.','Sensible. The emergency eggs are there for a reason.'),C('What would you order?','The mushroom noodles. Extra chilli if you enjoy consequences.',1,0,'noodles'),C('Are you recommending it or inviting me?','Recommending, tonight. I’m still at work. Another time, maybe.',0,1)),
 B('I manage the restaurant across the square. Being surrounded by food all day apparently doesn’t teach you to feed yourself.',
 C('I do that with my own work. Last thing I want at home.','Exactly. Thank you for understanding my takeaway habit.',1),C('Do you like the job?','Most days. I like a busy room when everyone’s having a good night.',1),C('Those hours would be hard for me.','They can be. My weekends happen on random Tuesdays.'),C('You could cook; I could handle washing up.','That is a much better offer than most staff benefits.',0,1),C('So you’re never free?','I’m free sometimes. Just not on the same timetable as everyone else.')),
 B('Important question: when someone says “we’ll share starters,” do they mean share, or protect their favourite with a fork?',
 C('Share. But tell me what you really wanted before it arrives.','Excellent. An adult negotiation over dumplings.',1,0,'share'),C('I’m ordering my own. I know myself.','Respect. Strong borders make peaceful meals.',1),C('Depends who I’m eating with.','A diplomatic answer. I’ll be watching the fork.'),C('I’d let you have the last one. Probably.','Careful. That’s the sort of promise people remember.',0,1),C('I don’t really care about food that much.','Fair. I’m surrounded by people who discuss lunch during breakfast.')),
 B('I’ve got to count the till. Before I go: was this a one-off dinner emergency, or are you usually up late?',
 C('Usually late. My best ideas arrive after midnight.','Same. Unfortunately, so do my worst online purchases.',1,0,'night_owl'),C('Early nights, normally. Today got away from me.','Then I’ll stop keeping you from dinner.'),C('It changes. I’m not always quick to answer.','No worries. Messages don’t expire.',1,0,'slow_reply'),C('I’d stay up a bit for a good conversation.','I’ll try to earn the lost sleep sometime.',0,1),C('Let’s leave the timetable for another day.','Fair enough. Enjoy the food.'))),
S('A day off, allegedly','An unhurried catch-up','Ben: “I’m going to put the phone away and actually have my day off. Nice talking. Catch you another time.”',
 B(({r})=>r.flags.includes('noodles')?'I finally ate the noodles I recommended. Still good. My professional reputation survives. How did you get on?':'Actual day off. I’ve done the washing and now feel absurdly accomplished. How’s your day?',
 C('Quiet. I’m making no attempt to be impressive.','Good. We can be unremarkable together.',1),C('Busy, but I can talk for a little while.','No rush. I’m capable of entertaining myself. Allegedly.',1),C('I tried your recommendation. Good call.','Wonderful. I’ll add “reliable about noodles” to my references.',1),C('Better now you’ve appeared.','That’s a nice thing to hear on a laundry day.',0,1),C('I haven’t really got time today.','Fair. Leave this here and reply whenever.')),
 B('A friend wants me to join a five-a-side team. It meets every Wednesday. I said maybe before checking a single shift.',
 C('Could you ask for that evening off regularly?','Maybe. I’m good at protecting everyone else’s days, less good with mine.',1),C('I prefer plans you can drop into.','Me too. But apparently teams dislike a goalkeeper with a flexible attitude.',0,0,'flexible'),C('A regular commitment might be good for you.','Probably. I just hate making a promise and missing it.',1,0,'reliable'),C('I’d come and heckle supportively.','“Supportive heckling” sounds suspiciously like my friends.',0,1),C('Just say no if you can’t do it.','True. “Maybe” is often just me postponing an awkward answer.')),
 B('What’s something you make time for even in a busy week?',
 C('Friends. Even if it’s only a quick call.','That matters. I have a friend who sends a single voice note every Tuesday.',1,0,'friends_time'),C('Time alone. I get tired of being available.','Understandable. Service work is a lot of being available.',1),C('Exercise, or at least getting outside.','I walk home after closing. Not glamorous, but it helps.'),C('I’m trying to figure that out. Work keeps winning.','Same boat. Mine has a menu attached.'),C('Dating, if I meet someone I like.','I’d like to get better at that part too.',0,1)),
 B('Would a short call sometime be nice? Easier than me sending essays about football I haven’t agreed to play.',
 C('Yes. Pick a time you’re actually off.','Thursday at seven? I’m down to leave at five.',1,0,'call_planned'),C('I prefer messages for now.','Easy. Essays about imaginary football it is.',1,0,'text_only'),C('Maybe later. I’m enjoying this pace.','No problem. There isn’t a deadline.',1,0,'slow'),C('I’d like that. I’m curious about your voice.','Now I’m going to be weirdly aware of my voice.',0,1,'call_planned'),C('Only if you can guarantee no interruptions.','I can choose a quiet time. I can’t guarantee the whole world behaves.'))),
S('Plans collide','A message before your planned chat','Ben: “I’ll go deal with the kitchen. Thanks for talking it through. I’ll follow up when I know the rota.”',
 B(({r})=>r.flags.includes('call_planned')?'I’m sorry. Someone’s ill and I need to stay late. I won’t make seven. Telling you now rather than leaving you waiting.': 'I thought I’d be free to chat tonight, but someone’s called in sick. I’ll be at work. Glad we didn’t book anything.',
 C('Thanks for letting me know. What other day works?','Tuesday afternoon is clear. I can check before we settle it.',1,0,'rebook'),C('Disappointing, but I understand. I kept the evening clear.','I’m sorry. You didn’t get that time back just because I had a reason.',1,0,'impact'),C('I’ll go out with friends instead. We can try another time.','Good plan. Don’t spend the evening waiting for me.',1,0,'own_plans'),C('Can we keep to messages until work calms down?','Yes. That’s probably more realistic this week.',1,0,'text_only'),C('If you wanted to talk to me, you’d leave work.','I can’t leave the staff to manage alone. That isn’t how it works.',-2)),
 B('I’m trying to find someone to cover more closing shifts. I’m also bad at saying no when people ask for swaps.',
 C('Those sound like two separate problems.','They are. I tend to solve the first by making the second worse.',1),C('I don’t need lots of time, but I need plans to mean something.','That’s fair. Better to promise one afternoon than three imaginary evenings.',1,0,'reliability'),C('My schedule’s odd too. We might manage.','That’s encouraging. We can compare our strange free hours.',1),C('I’d rather keep this casual if plans are uncertain.','Okay. I can understand that.',1,0,'casual'),C('You should find a different job.','I like my job. I’m trying to make it sustainable, not abandon it.',-1)),
 B('Sorry, that’s a lot about work. You said you had other things going on too. Anything good this week?',
 C('I caught up with someone I’d been missing.','That’s a good feeling. Even when nothing particularly happens.',1),C('I finished something I’d been putting off.','Excellent. Please lend me that skill.'),C('Nothing special. I don’t always have a good story.','You don’t need one. “Fine” is an acceptable report.',1),C('I was looking forward to talking to you.','I was too. I’d like to find a better time, properly.',0,1),C('I’d rather not change the subject yet.','Okay. What else do you need to say?',1)),
 B('Would you rather I suggest another time once the rota is settled, or leave it with you?',
 C('Please suggest something. I don’t want to chase it.','I will. A time I can actually keep.',1,0,'initiative'),C('Leave it with me. I’ll see what my week looks like.','Okay. No extra nudges.',1,0,'player_initiates'),C('Let’s have one afternoon and see how that goes.','A trial run. Sensible.',1,0,'trial'),C('I want to keep talking, even if the calendar’s messy.','I’d like that. I’ll still try to be less messy.',0,1),C('Promise it won’t ever happen again.','I can promise notice. I can’t honestly promise never.',-1))),
S('A plan that holds','A day he kept free','Ben: “Saturday at three. Corner café. I’m writing it down while we’re talking.”',
 B(({r})=>r.flags.includes('initiative')?'Rota sorted. I can do Saturday at three. I checked before sending this. Would you want to meet for coffee?':r.flags.includes('player_initiates')?'Good to hear from you. I kept this afternoon free. How’s the week looking now?':'I’ve finally got an afternoon that nobody has borrowed. Fancy making that coffee happen?',
 C('Yes. Let’s do it.','Good. I’m looking forward to it.',1,1),C('I’d be up for coffee as friends.','Okay. I appreciate knowing what you mean.',1,0,'friends','friends'),C('I’m still not sure the schedules will work.','Understandable. Coffee won’t magically change my hours.'),C('I like you. I want to give it a chance.','I like talking to you too. Let’s see how it feels in person.',0,1),C('I need you to impress me after cancelling.','I can show up. I don’t really want an audition.',-1)),
 B('Small confession: I almost offered to cook, then remembered inviting someone to my flat before meeting is a bit much.',
 C('A public place is better for a first meeting.','Agreed. Also, I don’t have to clean the kitchen first.',1),C('Coffee is enough. We don’t need a big production.','Excellent. I was in danger of creating a menu.',1),C('Save the cooking idea for another day.','Noted. Future me will have to live up to it.',0,1),C('I probably wouldn’t want a home date for quite a while.','Fine by me. Plenty of places outside my kitchen.',1),C('I wouldn’t have minded, but coffee works.','Then we can both have a relaxed afternoon.')),
 B('What are you hoping this turns into? No required answer. I just don’t want to assume because we’ve been chatting.',
 C('I’m open to dating, if it feels right.','Me too. Open is a good word.',1,1,'dating'),C('I’m meeting people. I’m not exclusive with anyone.','Same. If that changes, we should actually say it.',1,0,'open'),C('Friendship is more my pace right now.','Okay. Then let’s meet without pretending otherwise.',1,0,'friends','friends'),C('I don’t know yet. That’s why I want to meet.','Reasonable. We’ve mostly discussed noodles.'),C('I want a serious relationship eventually.','I’d like that too. Eventually is doing useful work there.',1,0,'serious')),
 B('If I’m a few minutes early, should I order, or wait?',
 C('Order. I don’t need you to sit there thirsty.','Good. Very practical romance.',1),C('Wait, if you don’t mind. I like choosing together.','Sure. I can survive five minutes.',1),C('Send me the menu and I’ll tell you what I want.','Efficient. Restaurant-approved.'),C('Surprise me, but nothing wildly sweet.','A manageable responsibility.',0,1),C('I’ll get my own. Easier.','Works for me.'))),
S('Off the clock','The corner café','Ben checks the bus time. “I’ve got nowhere to rush to for once. But I should let you get on with your day.”',
 B('“Ben. Hi.” He half-stands, then laughs at himself. “Handshake? Wave? I’ve already made it awkward.”',
 C('A wave is good. We’ve got time.','He waves from about a foot away. “Perfectly normal.”',1),C('I’d be happy with a hug, if you would.','“Yeah.” It’s brief and a little clumsy.',0,1),C('Good to meet you. Let’s sit.','“Good to meet you too.”',1),C('I’m awkward at this part as well.','“Great. Shared expertise.”',1),C('You look different from what I expected.','“I’m hoping that isn’t a complaint about the haircut.”')),
 B('His phone buzzes. He glances at the name. “Work. I told them I was off.” He turns it face down.',
 C('You can check if it might be urgent.','“They can call if it is. A group chat can wait.”',1),C('I appreciate you putting it away.','“I said I’d be here. I meant here.”',1,0,'noticed_effort'),C('Is that difficult for you?','“A bit. I’m trying not to confuse being useful with being available.”'),C('Good. I’d like you to myself for an hour.','“An hour I can do.”',0,1),C('If you pick it up again, I’m leaving.','“That seems a bit much. I’ve just put it down.”',-2)),
 B('You get onto cooking disasters. He admits to burning rice so thoroughly he threw the pan away. “Tell me something worse.”',
 C('I once followed the wrong recipe halfway through.','“Two dinners at once. Ambitious.”',1),C('I order takeaway before I can create a disaster.','“Prevention. Very sensible.”'),C('I’m actually a decent cook. You may be outmatched.','“Finally, a threat worth taking seriously.”',0,1),C('I don’t like trying to top every story.','“Fair. You don’t have to. I was enjoying talking nonsense.”',1),C('I’d rather hear about something other than food.','“Occupational hazard. Ask me about anything else.”')),
 B('There’s a comfortable pause. “I’ve had a good time,” he says. “Would you want another afternoon?”',
 C('Yes. Let’s plan a second date.','“I’ll check the rota. Properly.”',1,2,'second_date','romantic'),C('Yes, but I’d keep it friendly.','“Okay. I’d still like to see you.”',1,0,'friends','friends'),C('I’m attracted to you, but the schedule still worries me.','“I can’t fix it with a good afternoon. Take some time.”',1,1,'unsure'),C('I’m not feeling a romantic spark.','“Ah. Fair enough. Thanks for saying.”',0,0,'end_romance','friends'),C('Only if you agree to put me before work.','“Then I don’t think we should. I can make room, not that promise.”',-4,0,'end_romance','ended')))
];
stories.morgan=[
S('The long film','A cinema recommendation','Morgan: “I’m going to find dinner. Thanks for the recommendation. I’ll report back if I survive another long film.”',
 B('Hi, Morgan from the cinema thread. I watched the film you mentioned. Did you know it was nearly three hours, or was that part of the joke?',
 C('I forgot to warn you. Sorry about your evening.','I liked it. I just would have brought a better snack.',1),C('Three hours well spent, I hope.','Two and a half well spent. I have notes about the ending.',1),C('I haven’t finished it myself yet.','An adventurous recommendation. I respect the confidence.'),C('I like something I can get lost in.','Me too. Though I did get briefly lost looking for the exit.'),C('I was hoping you’d have something to tell me afterwards.','Well, your plan worked. I have opinions.',0,1)),
 B('I walked home afterwards. The city feels different when most of the shops are shut. Less like a list of errands.',
 C('I like that time of night too.','You notice strange little details. A light on in an empty office.',1,0,'night_walk'),C('I’d rather get home and be comfortable.','Understandable. My shoes were regretting my philosophy by the end.'),C('What did you notice?','Someone had put a tiny chair beside a tree. No explanation.',1),C('I’d go for a walk like that with someone.','Good company improves most wandering.',0,1),C('I don’t feel comfortable walking alone late.','Fair. I should have said it was a well-lit, busy route. Different people get a different city.',1)),
 B('I work in urban planning research, so I’m unfortunately paid to have opinions about pavements. What do you accidentally bring home from work?',
 C('Problems I can’t solve until the next day.','The worst unpaid overtime.',1),C('Stories. Usually about something ridiculous.','Those are the useful souvenirs.'),C('Not much. I try to keep work separate.','I’m trying to learn that. Bad buildings make it difficult.',1,0,'work_separate'),C('I’d rather leave work out of this for now.','Of course. We can return to the mysterious tiny chair.',1),C('You can tell me about pavements. I’m interested.','Dangerous permission. I’ll try not to become a public lecture.',0,1)),
 B('One more recommendation, then I’ll leave you alone: a film, a place to walk, or somewhere to eat?',
 C('A film under two hours, please.','A very reasonable restriction. I know a good one.',1,0,'short_film'),C('Somewhere to walk on a quiet afternoon.','The canal path after the bridge. Skip the first noisy stretch.',1,0,'canal'),C('Food. Recommendations should come with dinner.','The little bakery on Market Street. Go before they sell out.',1,0,'bakery'),C('Surprise me next time.','A small responsibility. I’ll think about it.'),C('Whichever one we could do together eventually.','Let’s keep talking and see. I’d like that possibility.',0,1))),
S('A different postcode','News, without a promise','Morgan: “I need to finish something before I start browsing flats again. Good talking to you.”',
 B(({r})=>r.flags.includes('canal')?'Did you ever try the canal path? I walked it again this week. I’m collecting favourite places, apparently.':r.flags.includes('bakery')?'The bakery sold out before I arrived. I’m withdrawing my endorsement until they bake more. How’s your week?':'I watched something under two hours. A revolutionary experience. How’s your week been?',
 C('Pretty ordinary. I’m okay with that.','Ordinary gets a bad reputation.',1),C('Busy. I could use a walk and a bakery.','A strong two-part treatment for a busy week.'),C('I’m trying something new this weekend.','Nice. Voluntary new thing, or did someone talk you into it?',1),C('I’ve been looking forward to another chat.','Me too. Glad you got in touch.',0,1),C('Not a great week. I’d rather hear about yours.','Okay. I can supply a distraction.')),
 B('I interviewed for a job in another city. Nothing decided. Four hours away, so close enough for my mum to say it’s close and far enough for trains to disagree.',
 C('Would it be a good job for you?','Very. More field work, less writing reports about other reports.',1),C('Would you want to move?','Part of me does. Part of me really likes my corner shop.',1,0,'move_curious'),C('I’m looking to date someone local, eventually.','Good to know. I don’t want to hide a possible move.',1,0,'local'),C('I’d miss these conversations if you disappeared.','Moving doesn’t have to mean disappearing.',0,1),C('Why start meeting people if you might leave?','Because nothing was certain. I’m telling you now rather than later.')),
 B('What keeps you in this city? Or is staying just the default for now?',
 C('My friends. Starting again sounds exhausting.','People are a very good reason to stay.',1,0,'roots'),C('Family. I’m not especially mobile.','That makes sense. Moving isn’t just a preference.'),C('Work, mostly. I could imagine somewhere else.','Same. Sometimes the practical thing becomes the whole plan.',1),C('I don’t know. I’ve never really asked myself.','I hadn’t until the interview came up.'),C('I could move for the right person.','Maybe, eventually. I’d want us both to have a life there, though.',0,1)),
 B('I’ll tell you when I hear. For now, can we talk about something that doesn’t require a spreadsheet?',
 C('Tell me about the tiny chair. Any developments?','It now has a tiny cushion. I’m invested.',1),C('What was the last thing that made you laugh?','A dog refusing to walk past a statue of another dog.'),C('Yes. I don’t need a future plan after two chats.','Agreed. I was trying not to make it A Big Announcement.',1),C('You’re allowed to be excited about it.','Thank you. I am excited. Nervous too.',1),C('I’d rather pause until you know about the move.','That’s fair. You can get back in touch when you want.',0,0,'wait_for_news'))),
S('An ordinary Saturday','A longer conversation','Morgan: “I promised my sister I’d call. Let’s pick this up another day.”',
 B('My sister asked me to babysit for two hours. We built a train track around every chair in her flat. It’s still there. Nobody can reach the kitchen.',
 C('Sounds like the train system is working as designed.','Excellent coverage. Terrible emergency access.',1),C('Did you enjoy it?','Yes. Very much. Then I enjoyed going home to silence.',1),C('I love spending time with children.','They do make you explain things you thought you understood.'),C('Children tire me out immediately.','The energy supply is mysterious and apparently unlimited.'),C('I’m more interested in whether you escaped.','I negotiated a bridge. Years of training finally useful.')),
 B('I like being the relative who visits. I don’t want children of my own. Not a dramatic announcement—I just don’t want to let anyone assume.',
 C('I don’t want them either.','Good to know. That does simplify one thing.',1,0,'no_kids'),C('I’m not sure yet. I wouldn’t want you to count on a no.','Thanks for being clear about the uncertainty.',1,0,'unsure_kids'),C('I do want children eventually.','Then romance probably wouldn’t be fair to either of us. I’d still enjoy getting to know you as a friend.',1,0,'end_romance','friends'),C('I’d rather talk about that when we know each other better.','Okay. Just know my answer isn’t likely to change.'),C('You might feel differently with the right person.','Please believe me about this. I’m not asking to be persuaded.',-3,0,'pressured_kids')),
 B(({r})=>r.path==='friends'?'I know that can make things feel different. Would you still want to talk? No pressure to relabel this immediately.':'I hope that didn’t turn a perfectly normal train story into an interview. I’m still enjoying talking to you.',
 C('I’d like to keep talking.','Me too. We can leave the big questions alone for a minute.',1),C('Let’s keep it friendly. I’d like that.','Okay. I’d like that too.',1,0,'friends','friends'),C('I need some time to think about what I want.','Of course. I’m not waiting for an answer tonight.',1),C('I appreciate knowing. It makes it easier to be honest.','That was the idea, even if my timing was awkward.',1),C('It was a lot to bring up.','I can see that. I didn’t want to let it become a surprise later.')),
 B('Smaller question: train route aside, are you someone who plans a weekend or sees what happens?',
 C('One plan, plenty of gaps.','That might be my ideal. Something to get out for, then room to wander.',1,0,'loose_plans'),C('I like knowing what I’m doing.','You’d get along with the side of me that makes lists.'),C('As little planning as possible.','A good way to discover places. Also a way to miss their opening hours.'),C('Depends who I’m spending it with.','Fair. People have different rhythms.',1),C('A quiet weekend together sounds good, eventually.','Eventually is a useful word. I can imagine that.',0,1))),
S('A decision, finally','Before you meet','Morgan: “Saturday at three. I’ll bring exactly zero maps. Unless you ask.”',
 B(({r})=>r.flags.includes('local')?'I remember you said you wanted someone local. I got the offer, and I’m taking it. I wanted you to know before we make any plans.':'They offered me the job. I said yes. Then immediately looked up how much moving boxes cost. It’s happening in two months.',
 C('Congratulations. You sounded excited about the work.','I am. Thanks. It’s nice to hear that before the practical questions.',1),C('I’m happy for you, but the distance doesn’t work for me romantically.','Understood. I’d still be up for a friendly coffee.',1,0,'end_romance','friends'),C('I’d still like to meet before deciding anything.','Same. A coffee doesn’t have to solve two months from now.',1),C('I’m interested enough to explore it. No promises yet.','That feels honest. I’m interested too.',0,1),C('If you liked me, you’d reconsider.','I’m taking the job. I’m not going to make it a test of liking you.',-3,0,'move_pressure')),
 B('Would the corner café work? Somewhere easy to leave if the conversation is terrible. Kidding. Mostly.',
 C('It works. Saturday afternoon?','Three? I’ll be there.',1),C('Let’s keep it to an hour for the first meeting.','Sensible. A manageable first expedition.',1),C('I’d rather just be clear that it’s friendly coffee.','Clear. Friendly coffee.',1,0,'friends','friends'),C('I’m hoping we won’t be in a hurry to leave.','Me too. But I’m trying to avoid promising a whole afternoon.',0,1),C('The joke makes you sound like you expect it to be bad.','Nerves, probably. I’m looking forward to it.')),
 B(({r})=>r.flags.includes('pressured_kids')?'One thing I do want to settle: I meant what I said about not having children. I need you to believe that.':'Is there anything you’d rather not be asked on a first meeting? I’d prefer not to spend it explaining my entire CV.',
 C('Fair. I can respect that.','Thanks. That’s all I need.',1),C('Family stuff can wait for me.','Of course. We can talk about things we actually enjoy.',1),C('I’m fine with most questions if I can pass on them.','Agreed. No compulsory answers.',1),C('I’d like to keep it light and see if we get along.','Good. We can save the life plans.'),C('You’re setting a lot of rules.','I’m telling you one preference. That doesn’t seem like much to ask.',-2)),
 B('I’ll message when I get there. In the meantime, any last cinema recommendations?',
 C('Nothing longer than ninety minutes. You’ve earned a rest.','A benevolent policy.',1),C('We should compare our terrible favourites in person.','Excellent. I’ll prepare my defence.',1),C('Let’s save a few things to talk about.','Good call. I’ll stop using up the material.'),C('Something we could watch together another time.','Let’s see how the coffee goes first. But I like the possibility.',0,1),C('No films. I want your tiny-chair investigation update.','There has been a development. You’ll have to wait.'))),
S('No maps required','The corner café','Morgan stands and puts their bag over one shoulder. “I should go. It was good to turn messages into an actual afternoon.”',
 B('“Morgan. Hi.” They nearly knock their bag off the chair while moving it. “An extremely graceful entrance, as you can see.”',
 C('I’ll pretend I didn’t see it.','“Already generous company.”',1),C('It’s good to meet you.','“You too.”',1),C('I’m nervous as well, if that helps.','“More than you’d think.”',1),C('You look nice.','“Thanks. I changed my shirt twice, which was unnecessary information.”',0,1),C('I imagined you quite differently.','“I probably imagined you differently too. Strange, isn’t it?”')),
 B('They point out a decorative doorway that goes nowhere. “Sorry. Occupational hazard. Tell me if I start lecturing about the building.”',
 C('No, explain it. I’d have walked past.','“That’s the thing—it used to be a shop entrance.” Their face brightens.',1),C('You get one building fact, then my turn.','“Fair allocation. I’ll choose carefully.”',1),C('I like seeing what catches your attention.','“That’s a very nice way of putting it.”',0,1),C('Architecture isn’t really my thing.','“Okay. I’ll keep it to myself unless the ceiling falls down.”'),C('Can we just have a normal date?','“This is normal conversation for me.”',-2)),
 B('The move comes up again. “I’m excited,” they say. “But I will miss having people nearby. I don’t want to make that your problem.”',
 C('We can keep talking without solving everything today.','“Yes. That’s enough for now.”',1),C('I don’t think I can do a long-distance romance.','“I understand. I’d rather know.”',1,0,'end_romance','friends'),C('I’d try visiting sometimes, if we both wanted it.','“We could see. No need to buy a ticket today.”',0,1),C('I need to find out how I feel after today.','“Me too.”',1),C('I still think you should stay.','“Then I think we’re going to keep having the same disagreement.”',-3,0,'end_romance','ended')),
 B('As the cups empty, they ask, “Would you want another afternoon before I go?”',
 C('Yes. A second date, if you want that too.','“I do.” They smile.',1,2,'second_date','romantic'),C('Yes, as friends.','“I’d like that.”',1,0,'friends','friends'),C('I’d rather leave it as a good afternoon.','“Okay. I’m glad we met.”',0,0,'end_romance','friends'),C('Let me think about the distance first.','“Take your time. You know where I stand.”',1,0,'unsure'),C('Only if you can promise we’ll make it work.','“I can’t promise that. I’m not sure anyone could.”',-1)))
];
stories.maya=[
S('The mystery chair','A flea-market question','Maya: “I have to go persuade a client that the logo cannot be bigger than the page. Good luck with the chair.”',
 B('Hi, Maya from the local group. That chair you posted is probably seventies, possibly a very committed imitation. Did you buy it?',
 C('Yes. I liked it before I knew anything about it.','Best reason. People get very strange about whether liking a chair is correct.',1),C('Not yet. I was hoping someone would talk me out of it.','I may be the wrong person. I own three lamps I don’t have surfaces for.'),C('I left it. No room.','A level of restraint I can only admire.',1),C('I mainly wanted an excuse to ask somebody about it.','Then the chair has already done useful work.',0,1),C('I don’t really care what decade it’s from.','Fair. If it holds a person up, it’s doing its main job.')),
 B('I’m a designer. Apparently that means friends send me pictures of furniture and ask whether it’s “a thing.” Everything is a thing. Some things wobble.',
 C('Does your own flat look carefully designed?','Carefully designed around a drying rack. Very modern.',1),C('Do you enjoy that, or does it feel like unpaid work?','A quick opinion is fun. A whole room with a deadline is a job.',1),C('I’d be useless at matching furniture.','Matching is optional. Measuring doorways is less optional.'),C('You could help me choose something over coffee one day.','Possibly. I’d prefer coffee without a design brief attached.',0,1),C('I’d expect friends to help each other for free.','Help, yes. Whole projects, no. It can get blurry.',-1)),
 B('My latest project is painting a cupboard. It currently looks worse than before I started. I’m told this is part of the process.',
 C('I like a project with a messy middle.','Good. You’d feel very at home beside this cupboard.',1,0,'projects'),C('That stage would make me want to quit.','It has crossed my mind. The paint’s paid for, though.'),C('What colour are you going for?','Dark green. The sample looked sophisticated. The cupboard looks damp.',1,0,'green'),C('I’d rather pay someone who knows what they’re doing.','If I had the budget, that would be tempting.'),C('I could keep you company while you regret the paint.','A useful supporting role.',0,1)),
 B('Enough furniture. What kind of thing gets you absorbed for an afternoon?',
 C('Making or fixing something.','Very satisfying when it works. Loudly frustrating when it doesn’t.',1),C('A game or a book. I like disappearing into a world.','Same. Especially when there’s real-world paint drying.'),C('Seeing friends, with no complicated plan.','A good afternoon needs very little equipment.',1),C('Cooking. Sometimes ambitiously, sometimes badly.','Then we have that in common. I choose recipes with too many steps.',1,0,'cooking'),C('I’m between hobbies at the moment.','That happens. You don’t need a polished answer.'))),
S('The free exhibition','Something to do without a booking','Maya: “I’m heading out before I spend the whole afternoon deciding what to wear. Talk later.”',
 B(({r})=>r.flags.includes('green')?'Cupboard update: the green dried much nicer. I’ve stopped apologising to it. How’s your week?':'The cupboard is finished. I now have a place to hide all the things I used to leave on the floor. Progress.',
 C('Congratulations. Did you celebrate?','Made tea and opened the doors repeatedly. A private ceremony.',1),C('Are you starting another project already?','Trying not to. I saw a very sad table yesterday.'),C('I like that you stuck with it.','Me too. It’s nice when persistence produces furniture.',1),C('You sound pleased. It’s nice hearing that.','I am pleased. Thanks for noticing.',0,1),C('I’m having a less productive week.','You don’t have to produce a cupboard to qualify as a person.')),
 B('There’s a free exhibition at the old station this weekend. My friend wants to go to the expensive immersive thing instead. I’m lobbying for free.',
 C('Free sounds good. Expensive doesn’t automatically mean better.','Exactly. Also, I can leave after twenty minutes without resentment.',1,0,'budget'),C('I’d pay more for something special now and then.','Me too, if it’s actually special. Not just projected onto a wall.'),C('What do you want to see?','The photographs at the station. Local shops before they closed.',1),C('I’d enjoy either with the right person.','That’s a diplomatic answer with suspiciously good timing.',0,1),C('I don’t really like exhibitions.','Fair. Standing thoughtfully in a room isn’t everyone’s weekend.')),
 B('I’m trying to keep spending sensible. Freelance work has been patchy. I’m fine; I just don’t want to pretend I’m having fancy nights out.',
 C('We don’t need fancy plans to get to know each other.','Good. I’d much rather say that plainly.',1),C('Thanks for telling me. I like knowing what works.','I was worried it would make things awkward. This is better.',1),C('I enjoy expensive outings, but I can do cheaper things too.','That seems fair. I don’t need our preferences to be identical.'),C('I could pay if we go somewhere together.','Kind, but I’d rather choose something we can both comfortably afford.',0,1),C('Does that mean you’re always worried about money?','Not always. But I do pay attention to it.')),
 B('If you had a free afternoon and almost no budget, what would you do?',
 C('Walk, get a coffee, look in shops without buying anything.','The dangerous phrase is “without buying anything.”',1),C('Cook something from whatever’s in the kitchen.','A cupboard challenge. I like it.',1,0,'pantry'),C('Stay home. Free and comfortable.','A defensible plan.'),C('Find some free live music.','There’s often something at the market. I forget to look.'),C('Ask you to show me the exhibition.','Maybe. Let’s keep that idea.',0,1))),
S('A favour, with edges','An ordinary evening','Maya: “I’m closing the laptop. It’s time to look at something that isn’t a rectangle.”',
 B('Can I ask you something slightly annoying? A friend wants me to design their business menu. They keep calling it a “quick favour.” It isn’t quick.',
 C('Have you told them how much work it actually is?','Not clearly enough. I’ve been hoping they’d magically know.',1),C('I’d give them a price before starting.','That would save a lot of resentment. I should do that.',1,0,'clear_price'),C('I might do a small version, if I could keep it small.','The dangerous part is whether we agree what small means.'),C('Do you want advice, or to complain for a minute?','Complain first. Advice once I’ve become reasonable.',1,0,'listen'),C('You’re lucky they want your work.','Wanting it and paying for it are different things.',-2)),
 B('They said I’d make it look nice “without really trying.” I think they meant it as a compliment. It landed badly.',
 C('They made your skill sound effortless, so the work disappeared.','Yes. That’s exactly what annoyed me.',1),C('I can see how they meant well and still irritated you.','I think that’s the version I need to remember.',1),C('I’d tell them that sentence bothered me.','I might. Without sending the furious first draft.'),C('I don’t think I’d have read it that way.','Fair. Maybe it hit a nerve because of the timing.'),C('You’re looking for something to be offended by.','I’m telling you why it hurt. You don’t have to agree, but that feels dismissive.',-2,0,'dismissed')),
 B('Do you find it easy to ask for help? I seem to alternate between doing everything myself and asking at the last possible minute.',
 C('I ask early. It gives people room to say no.','That’s a good point. Last-minute requests make everything feel urgent.',1),C('I hate asking. I’d rather struggle a bit.','Same. Not always our finest quality.',1),C('Depends who it is. I don’t want help with strings attached.','Yes. The invisible invoice is unpleasant.'),C('I like helping people I care about.','Me too. I just want it to stay a choice.',0,1),C('I’d rather keep this conversation lighter.','Of course. The menu saga can stop here.',1)),
 B('Lighter question, then: I’m making dinner and the recipe asks for something I definitely don’t own. Substitute, go shopping, or abandon the entire plan?',
 C('Substitute. Dinner doesn’t know the recipe.','A liberating philosophy.',1,0,'improvise'),C('Go shopping. I like knowing how it’s supposed to taste.','Fair. You would save me from many experimental meals.'),C('Abandon it. Toast is a legitimate pivot.','At least the toast wouldn’t require a specialist ingredient.'),C('Tell me what it is. We can work something out.','A teaspoon of something wildly specific. Let’s investigate.',1),C('I’m more interested in who gets invited to taste it.','At this stage, nobody I want to keep liking me.',0,1))),
S('A manageable invitation','Coffee plans','Maya: “Saturday at three. I’ll get there a little early. I’m looking forward to it.”',
 B(({r})=>r.flags.includes('clear_price')?'I sent a quote for the menu. They said yes. All that worrying and a perfectly normal conversation. Anyway—would you fancy coffee?':r.flags.includes('dismissed')?'I wanted to say: I didn’t enjoy being told I was looking for offence. I’d still like to know you, but not if that’s how disagreements go.':'The menu situation is sorted. I’ve got a little more space in my head. Would you fancy meeting for coffee?',
 C('Yes. Somewhere simple would be good.','Simple sounds perfect.',1,1),C('I’d like to meet as friends.','Okay. I appreciate the clarity.',1,0,'friends','friends'),C('Thanks for being clear with me. I’d like to meet.',({r})=>r.flags.includes('dismissed')?'Thanks. I’d like to give this a fresh start.':'Good. It’ll be nice to talk without a screen.',2,0,'repair'),C('I’m interested, but I’m a slow starter.','That’s fine. I’m not planning beyond one coffee.',1),C('You need to stop overthinking things.','That isn’t especially reassuring.',-2)),
 B('The corner café is reasonably priced. I’d rather we each got our own, at least this time. Less awkward for me.',
 C('Works for me.','Good. One tiny awkward conversation avoided.',1),C('I usually offer to pay, but I’m happy to split.','Thanks. It’s the accepting my answer part that matters.',1),C('I’d like to treat you sometime, if you want that.','Maybe another time. I appreciate you asking.',0,1),C('I prefer splitting too.','Excellent. We can use the saved discussion time on biscuits.',1),C('No, I’m paying. Don’t argue.','I just told you what would make me comfortable.',-3,0,'money_pressure')),
 B('Do you like knowing exactly what a meeting is, or do you prefer seeing what happens?',
 C('I’d call it a date. If you’re comfortable with that.','I am. I like being asked directly.',1,1,'dating'),C('Let’s call it coffee and see.','That works. We can talk about it afterwards.',1),C('Friendly coffee. I don’t want you to expect romance.','Understood.',1,0,'friends','friends'),C('I’m meeting other people too. I’d rather say that.','Same here. We haven’t agreed otherwise.',1),C('Labels make it feel like work.','I don’t need a label, just not to be guessing forever.')),
 B('I’ll try not to arrive covered in paint. Do you have a first-meeting habit I should know about?',
 C('I arrive early and pretend it was accidental.','Perfect. We can both be casually there twenty minutes ahead.',1),C('I’m quiet until I settle in.','I won’t try to fill every second.',1,0,'quiet_start'),C('I make terrible jokes when I’m nervous.','I’m generous with a first terrible joke.'),C('I’ll probably compliment you and then forget every other word.','I’ll try not to make that worse.',0,1),C('No special habits. I’ll see you there.','See you there.'))),
S('A real afternoon','The corner café','Maya checks the time. “I need to go before I lose the whole day in here. In a good way.”',
 B('“Maya. Hi.” There is a tiny fleck of green paint on her sleeve. She notices you notice. “The promise was aspirational.”',
 C('The cupboard colour? I’m impressed it followed you.','“It’s committed to the friendship.”',1),C('Good to meet you.','“You too.”',1),C('I like the colour on you.','“Unconventional styling, but thank you.”',0,1),C('I’m relieved you look like someone with a normal day.','“Extremely normal. I did laundry before this.”'),C('I thought you’d dress up more.','“I thought this was coffee.”',-2)),
 B('You order separately. She spots a menu with spectacularly bad spacing and turns it over. “I am choosing peace.”',
 C('You’re allowed one professional complaint.','“The numbers don’t line up. That’s it. I’m done.”',1),C('I’d never notice unless you pointed it out.','“Now you’ll see it everywhere. Sorry.”'),C('I like that you notice things.','“Even very small, irritating things?” She smiles.',0,1),C('Please don’t critique the whole café.','“Fair. I’m here to talk to you.”',1),C('Could you fix my friend’s business cards?','“Not while I’m having coffee, please.”',-1)),
 B('She asks what you do when a plan goes wrong. “I’m trying to become less attached to my imaginary perfect version of a day.”',
 C('Usually annoyed for ten minutes, then I adjust.','“Ten minutes seems reasonable. I’ll aim for that.”',1),C('I prefer a backup plan.','“You’d be useful company when it rains.”'),C('Sometimes the improvised version is better.','“Sometimes. My experimental dinner disagrees.”',1),C('I get frustrated. I’m working on it.','“Same. I like that answer better than pretending.”',1),C('I’d rather find out by spending time together.','“Fair. Fewer interview questions.”',0,1)),
 B('Outside, she pauses beside the window. “Would you want to do something again? Maybe the exhibition next time.”',
 C('Yes. I’d like another date.','“Me too.”',1,2,'second_date','romantic'),C('I’d enjoy the exhibition as friends.','“Okay. I’d enjoy that.”',1,0,'friends','friends'),C('I like you, but I’m still figuring out the attraction.','“Thanks for being honest. Take a bit of time.”',1,0,'unsure'),C('I don’t think another date is right for me.','“Okay. It was good meeting you.”',0,0,'end_romance','friends'),C('Only if you let me pay next time.','“I don’t want that to be a condition.”',-2)))
];
stories.daniel=[
S('A spare ticket','The community film night','Daniel: “I need to make dinner. Let me know about the film whenever you decide. Nice talking.”',
 B('Hi, Daniel here. You asked about the spare film ticket. It’s still available. No obligation to sit through my opinions afterwards.',
 C('I might take you up on both the ticket and the opinions.','A generous response. I’ll try to have interesting ones.',0,1),C('What’s the film? I replied before checking.','A comedy about a disastrous family holiday. Relatable, hopefully.'),C('I’m not sure I can make it.','No problem. I’ll offer it elsewhere if you can’t.'),C('That was kind of you to offer it in the group.','Better than letting it go unused.',1),C('Why have you got a spare?','A friend’s ill. Less interesting than a dramatic backstory.')),
 B('I’m fairly new to the group. Been in the area years, but only recently started going to things on my own.',
 C('It can be strange the first few times.','Yes. I’ve got quite good at appearing busy with a cup of tea.',1),C('I like doing things on my own. No negotiation.','That part is nice. Picking the film without a committee.'),C('What made you join?','Wanted my week to include more than work and the supermarket.',1),C('I’m glad you did.','Me too, so far.',0,1),C('You sound like you need to get out more.','That was more or less the idea.')),
 B('For context, I’m divorced and have a six-year-old daughter half the week. That’s why my availability looks oddly specific. Not a secret second life.',
 C('Thanks for telling me. What do you like doing together?','She’s currently teaching me how to draw dragons. I’m a poor student.',1,0,'asked_child'),C('I’m not sure dating a parent would suit me.','That’s fair. Better to know it might matter.',1,0,'parent_unsure'),C('I’d be comfortable getting to know you without meeting her.','That’s what I’d want. Those parts of my life stay separate for a while.',1,0,'respect_parent'),C('I’m mainly looking for friends, so no issue.','Good to know. Friends are welcome.',1,0,'friends','friends'),C('Does your ex cause a lot of trouble?','We manage things together. I’d rather not talk about her like that.',-1)),
 B('Outside work and parenting, I’m trying to remember what I actually enjoy. Turns out I still like a good film and a long walk. Very radical.',
 C('Ordinary things count.','I need reminding of that occasionally.',1),C('I’m trying to rediscover a few things too.','Maybe we can trade recommendations as we go.',1),C('I like someone with a settled routine.','Mine has moving pieces, but mostly it holds.'),C('I’m more spontaneous. We might have different rhythms.','Possibly. It doesn’t hurt to find out.'),C('Coffee with someone new could go on your list.','I’ll pencil it in as a possibility.',0,1))),
S('An early walk','A quiet catch-up','Daniel: “I’m off to collect my daughter. The dragon lesson resumes. Talk another day.”',
 B('I tried going for a walk before work. It was peaceful until a delivery van reversed beside me for an entire street. How’s your day?',
 C('Better than being followed by a beeping van.','An achievable standard.',1),C('I’m not a morning person. That sounds heroic.','Neither am I, really. I just put my shoes on before I could object.'),C('I like an early walk. Everything feels less crowded.','Exactly. Apart from the van.',1,0,'early'),C('A bit rough. I could use a distraction.','I can offer a very detailed account of an ordinary walk.'),C('Nice to hear from you.','Nice to talk again.',0,1)),
 B('I passed a repair café. People were fixing kettles and lamps. I like the idea of keeping things going instead of replacing them.',
 C('I’d enjoy learning how to fix something.','Me too. Less mysterious than staring at a broken switch.',1,0,'repair_cafe'),C('I keep things for far too long already.','Same. There’s a drawer in my kitchen that needs an intervention.',1),C('Sometimes replacing it is worth the saved time.','True. Not every toaster needs a heroic rescue.'),C('Are you the person everyone asks to fix things?','Sometimes. I’m trying to say when I don’t know.'),C('You could teach me something practical one day.','Only something I actually know. I don’t want to injure either of us.',0,1)),
 B('Are you someone who keeps in touch every day, or happily picks up a conversation after a gap?',
 C('Gaps are fine. People have lives.','That suits me. I prefer a proper chat to obligatory updates.',1,0,'gaps'),C('I like daily contact once I know someone.','Good to know. I can do some contact, but not always a long conversation.'),C('I’d rather agree what works than guess.','Yes. Guessing uses a surprising amount of energy.',1),C('It depends how close we become.','That seems reasonable.'),C('I like a lot of attention when I’m dating.','I might not be the best at constant attention. I’m glad you said it.')),
 B('A friend asked whether I’m dating seriously or just getting out again. I said “getting to know people.” Apparently that wasn’t a satisfying answer.',
 C('It’s a perfectly good answer at this stage.','Thank you. I thought so.',1),C('I’m interested in something serious eventually.','I could be too. I’d want to take it slowly.',1,0,'serious'),C('I’m not looking for a committed relationship.','Okay. Useful to know.'),C('I’m open to seeing where this goes with you.','I’d like to keep finding out.',0,1),C('You should know what you want before talking to anyone.','I know I want to be honest and take my time. I think that’s enough to begin.',-1))),
S('A change of plan','A scheduling conversation','Daniel: “Thanks for talking. I need to sort tomorrow’s school things. I’ll get back to you when the weekend is clearer.”',
 B('My daughter’s school has changed the date of a performance. It lands on the evening I thought I’d be free. I need to move our longer chat.',
 C('Of course. Tell me another time that works.','Thank you. Saturday afternoon looks clear.',1),C('I understand, though I was looking forward to it.','Me too. I’m sorry to change it.',1,0,'disappointed'),C('Let’s stick to messages for a bit.','That might make this week simpler.',1),C('I’ve got other plans I can make. We’ll find a day.','Good. I don’t want you waiting around for me.',1),C('Can’t her other parent go instead?','We’ll both be there. It matters to her.',-2)),
 B('I don’t want to make promises about being endlessly available. I can make time for someone, but some things won’t be flexible.',
 C('I can work with that if the plans we make are reliable.','That’s what I’d aim for.',1,0,'reliable'),C('I’m realising I want more freedom than that.','I appreciate you saying so.',1,0,'parent_unsure'),C('I’d rather know the actual situation.','Me too. No idealised version of my calendar.',1),C('I’m still interested. I don’t need every evening.','That’s nice to hear.',0,1),C('A relationship should become your first priority.','My daughter will remain a priority. I can’t bargain with that.',-3,0,'priority_pressure')),
 B('Changing subject for a minute: the dragon drawing is improving. Mine, not hers. Hers was already excellent.',
 C('Has she given you a grade?','“Nearly a dragon.” I’m considering framing that review.',1),C('It sounds like you have a good time together.','We do. Usually. Bedtime can be less glowing.',1),C('I don’t mind hearing about her, but I’d like to know more about you.','Fair. I sometimes hide behind parent stories.',1),C('What did you like drawing as a child?','Maps. Places that didn’t exist. I’d forgotten about that.'),C('Can we keep parenting stories out of this?','I can talk about other things, but she’s part of my life.')),
 B('Something about me, then: I used to play piano badly. I’m thinking about starting again, without needing to be good. Do you have anything like that?',
 C('Something I stopped because I wasn’t immediately good at it.','That is painfully familiar.',1),C('I enjoy a hobby I’m absolutely mediocre at.','A skill I’d like to acquire.',1),C('I like getting good at things. Progress is the fun part.','That makes sense. I just get impatient with the beginning.'),C('I’d listen to some bad piano.','A very generous offer. Possibly one you’d regret.',0,1),C('Nothing comes to mind.','No requirement to produce a charming hobby on demand.'))),
S('A quiet plan','Arranging coffee','Daniel: “Saturday at three. I’ll send the table number. I’m looking forward to seeing you.”',
 B(({r})=>r.flags.includes('priority_pressure')?'I’ve thought about our last conversation. I can date, but I can’t promise to put a relationship above my daughter. Is that something you can genuinely accept?':'I found an afternoon that works. Would you like to meet for coffee? Somewhere quiet enough to actually hear each other.',
 C('I’d like that. A quiet café sounds good.','The corner place is usually calm in the afternoon.',1,1),C('I’d like to meet as friends.','I’d enjoy that.',1,0,'friends','friends'),C('I need to be realistic about what I can accept. Let’s keep it friendly.','That sounds sensible.',1,0,'end_romance','friends'),C('I’m interested, and I can take it slowly.','That suits me.',1,1),C('I still think you should make more room for romance.','I’m making room. I’m not changing the part I’ve been clear about.',-2)),
 B('Just so there’s no confusion: I wouldn’t introduce someone I’m dating to my daughter early on. I’d want a relationship to be stable first.',
 C('That makes sense to me.','Good. I’d rather say it plainly.',1),C('I’d prefer that too. We should get to know each other first.','Exactly.',1),C('I don’t know what that would be like, but I respect it.','That’s enough for now.',1),C('I’d like to understand your life without rushing into it.','I appreciate that.',1),C('It would make me feel like you were hiding me.','That isn’t the reason. I’m trying to protect her from uncertainty.',-1)),
 B('I’m a bit out of practice with first dates. Does coffee still come with a set of rules I’ve forgotten?',
 C('Mostly don’t turn it into a job interview.','I’ll leave the competency questions at home.',1),C('We can just be two people having a drink.','That sounds manageable.',1),C('I’d like it to feel like a date, if we’re both interested.','I am interested. Just a little rusty.',0,1),C('I’m nervous too. We can be honest about it.','Good. Pretending is tiring.',1),C('I don’t think there are rules, beyond basic courtesy.','I can manage courtesy.')),
 B('Would you want a short walk afterwards if we feel like it, or keep the plan to coffee?',
 C('Let’s decide when we’re there.','Perfect. No obligation to extend it.',1),C('Coffee only this time. I have another plan afterwards.','Of course. Thanks for saying.',1),C('A walk would be nice.','There’s a pleasant route nearby.',0,1),C('I’ll probably need a bit of time before deciding.','Take it. We don’t need a complete itinerary.'),C('I don’t like adding things to plans.','Then coffee it is.'))),
S('A table for two','The corner café','Daniel puts on his coat slowly. “I’ve enjoyed this. Thanks for making the time.”',
 B('“Daniel. Hi.” He smiles, then moves his cup to make room for yours. “Was the journey okay?”',
 C('Yes. It’s good to meet you.','“You too.”',1),C('I got here too early and walked round the block.','“Same. We probably passed each other.”',1),C('I’m a bit nervous.','“Me too. We can retire that information and get on with it.”',1),C('You have a nice smile.','“Thank you.” He looks pleased and a little surprised.',0,1),C('I’m still adjusting from messages to a real person.','“Yes. It’s a strange jump.”')),
 B('He asks about something you mentioned earlier, then catches himself. “I’m not trying to test whether I remembered correctly.”',
 C('I like that you remembered.','“I was interested.”',1,1),C('My week’s changed since then. Let me tell you.','“Go on.”',1),C('I don’t mind a fresh start in person.','“Fair enough. Clean slate.”'),C('I’m impressed. I forget small details.','“I remember some and lose my keys every morning.”'),C('It feels a little intense.','“Sorry. I’ll ease off.”',0,0,'less_intense')),
 B('The conversation turns to routines. “My quiet evenings probably sound dull on paper. I like them.”',
 C('Dull on paper can be lovely to actually live.','“Exactly. Tea isn’t much of a plot.”',1),C('I need more going out than that, I think.','“That’s useful to know. I do go out, just not constantly.”'),C('I like a mix of ordinary nights and occasional adventures.','“That sounds close to what I’d want.”',1),C('I could imagine enjoying a quiet evening with you.','“I could too.”',0,1),C('You sound settled in ways I’m not ready for.','“Maybe. We don’t have to force a match.”',1,0,'mismatch')),
 B('“Would you want to do this again?” he asks. “No pressure to answer just because I’ve asked in person.”',
 C('Yes. I’d like a second date.','“I’d like that.”',1,2,'second_date','romantic'),C('I’d like to see you as a friend.','“Okay. I enjoyed talking.”',1,0,'friends','friends'),C('I need to think about whether our lives fit.','“Take your time. It’s a fair question.”',1,0,'unsure'),C('I don’t feel the attraction I hoped for.','“I understand. Thank you for saying.”',0,0,'end_romance','friends'),C('Only if you can be more spontaneous next time.','“I can plan something different. I can’t promise a different life.”',-1)))
];
stories.sam=[
S('The stubborn lock','A practical introduction','Sam: “Back to the repair stand for me. Good luck with the lock. Please don’t let it win.”',
 B('Hi, Sam from the group. Did you get your bike off that rack? The last person ended up carrying the whole thing into the café for help.',
 C('Got it eventually. Mostly through stubbornness.','A respected repair technique.',1),C('Not yet. I’m beginning to take it personally.','Try taking the pressure off the shackle before turning the key. Gently.'),C('A friend helped. I’m pretending I did most of it.','Naturally. Team effort, individual credit.'),C('I think I need a new lock.','Probably. I fix bikes; I’m not emotionally attached to terrible locks.'),C('I was hoping the helpful mechanic might come to my rescue.','Helpful mechanic is at work. But the advice is free.',0,1)),
 B('I work at the bike shop round the corner. Half the job is repairs. The other half is convincing people a noise won’t improve if they ignore it.',
 C('I’m guilty of waiting for noises to go away.','Most people are. Sometimes the noise is a bill getting larger.',1),C('I like knowing how things work.','Me too. Things are usually less mysterious once you open them.',1,0,'mechanical'),C('I’d rather leave repairs to someone competent.','A sensible form of self-knowledge.'),C('Do you enjoy the work?','Mostly. I like sending someone away with a bike they’re happy to ride.',1),C('So are you always covered in oil?','Only on the days with a “day” in them.')),
 B('Outside work I ride with a few friends. Nothing heroic. We usually undo the exercise at a bakery.',
 C('The bakery sounds like the important part.','Finally, someone understands the club’s mission.',1,0,'bakery_rides'),C('I’d be interested in an easy ride.','Easy is the actual plan, not something fast people say to trick you.',1,0,'ride_interest'),C('I’m not sporty at all.','That’s fine. I don’t need everyone to share my hobby.'),C('I prefer doing exercise on my own.','Also fair. Groups can become a whole social obligation.'),C('I might be persuaded by the company.','We’ll see whether my bakery choices live up to that.',0,1)),
 B('I’ve got to get back to a wheel that refuses to be straight. Is it okay if I say hi another time, or was this strictly lock support?',
 C('Say hi. It’s been nice talking.','Will do. No lock required.',1),C('I’d be up for chatting again. I’m not always quick to reply.','Fine. Neither am I when I’ve got a wheel in my hands.',1),C('Friendly conversation sounds good.','Good. I can provide that.',1,0,'friends','friends'),C('Definitely more than lock support.','Noted. I’ll try to have another topic ready.',0,1),C('Let me message you when I’m free.','Sure. Over to you.',1,0,'player_initiates'))),
S('The quiz team','An invitation with an easy out','Sam: “I’m heading off. If we win, I’ll be unbearable for approximately an hour. Speak soon.”',
 B('Pub quiz tonight. We need someone who knows anything about geography because apparently none of us have looked at a map. Do you enjoy quizzes?',
 C('Yes, but I’m not claiming to be useful.','Perfect. Overconfidence is our main problem.',1,0,'quiz'),C('I like them until somebody takes winning too seriously.','Same. A disputed point is not a court case.',1,0,'low_stakes'),C('Big groups aren’t really my thing.','Fair. It can be noisy and quite a lot of people at once.',1,0,'small_group'),C('I’d rather get to know you one-to-one first.','That makes sense. Another time, then.',1,1,'one_to_one'),C('I’m competitive. Consider yourself warned.','Useful warning. I reserve the right to laugh if we come last.')),
 B('My friends are a big part of my week. We’ve known each other ages. Sometimes I forget how intimidating that can look from outside.',
 C('It’s nice that you’ve kept those friendships.','I’m lucky. We’re annoying, but reliable.',1),C('I’d need a little time to settle into a group.','Then we wouldn’t throw you into the deep end.',1),C('I’d rather keep separate social lives as well.','I would too. I don’t need a relationship to swallow everything.',1,0,'independent'),C('I usually make friends easily.','Handy. I tend to introduce people and then panic about forgetting a name.'),C('I’d expect you to spend less time with them if we dated.','I’d make room for someone. I wouldn’t disappear from my friendships.',-2)),
 B('One friend suggested a team name based on my terrible parking. I ride bikes for a reason. What’s your tolerance for being teased?',
 C('High, if I know people like me.','Exactly. Context does a lot of work.',1,0,'teasing'),C('Some, but I don’t like being the whole joke.','Fair. There’s a line between joining in and being volunteered.',1,0,'gentle'),C('I’d rather people asked before making it public.','Reasonable. Especially in a group chat.',1,0,'private'),C('I give as good as I get.','Then you’d probably survive my friends.'),C('I’m more sensitive than I look.','Thanks for telling me. I’d rather know.',1,0,'gentle')),
 B('Last question before I leave: which quiz category would you volunteer for?',
 C('Music. But probably the wrong decade.','We have every wrong decade covered. You’ll fit right in.',1),C('Films. No promises about awards.','Plot knowledge counts. Usually.'),C('General knowledge. A little about everything.','The backbone of an unreliable team.'),C('I’d just be there for the company.','That’s a perfectly good reason.',0,1),C('I’m sitting this one out. Tell me how it goes.','Will do. No recruitment pressure.',1))),
S('A joke that lands oddly','A quieter conversation','Sam: “I should go feed the cat before she files a complaint. Thanks for talking.”',
 B('Quiz update: fourth out of six. We are describing it as “top four.” I made a joke in the group about the bike-lock saga, then wondered if that was unfair. No name attached.',
 C('That’s fine with me. It was funny.','Good. I did wonder after I hit send.',1),C('I’d rather you checked before using my stories.','Fair. Sorry. I’ll ask next time.',1,0,'privacy_boundary'),C('I don’t mind this one, but don’t make it a habit.','Understood. One terrible lock does not become your whole personality.',1,0,'privacy_boundary'),C('What did you actually say?','That the rack had claimed another victim. Not a dramatic account.'),C('I don’t like being made fun of.','I’m sorry. I meant the lock, but I can see why it felt personal.',1,0,'hurt')),
 B(({r})=>r.flags.includes('private')||r.flags.includes('gentle')?'You did mention being careful with teasing. I should have remembered that.':'I’m used to friends making jokes about everything. That’s not automatically how everyone wants to be treated.',
 C('Thanks for hearing me. We can move on.','Okay. I’ll be more careful.',1,0,'repair'),C('It matters more what happens next than the apology.','Fair. I’ll show you, rather than argue about my intentions.',1),C('I’m comfortable with teasing once we know each other better.','That gives me a useful line.',1),C('I honestly wasn’t bothered.','Then I’ll stop making a whole meeting out of it.'),C('I want you to stop telling your friends about me at all.','I can keep personal stories private. I’m not going to pretend I don’t know you.')),
 B('Different subject: a friend’s birthday ride is coming up. I want to go, but I’ve had very little quiet time lately.',
 C('Could you go for part of it?','Yes. I tend to treat plans as all-or-nothing for no good reason.',1),C('I’d take the quiet day if you need it.','Tempting. My cat has a strong stay-home agenda.'),C('I usually feel better once I get out.','Often true for me too. Hard to tell in advance.'),C('I’m glad you have your own things going on.','Good. I’d want you to keep yours too.',1,0,'independent'),C('If we were dating, I’d want that free time.','Some of it, sure. Not all of it.',-1)),
 B('Are you more comfortable making a plan days ahead, or checking in on the day?',
 C('Ahead. I like knowing what I’m keeping free.','Then I’ll ask ahead.',1,0,'planned'),C('On the day, if I’m free.','Works for casual things. Bigger plans need a bit more warning.'),C('A rough plan, then confirm nearer the time.','That might be my preferred version.',1,0,'confirm'),C('I’d make time for you if you asked.','That’s nice. I’d still rather ask properly.',0,1),C('It depends how important the plan is.','Fair. Coffee and a weekend away are different categories.'))),
S('A smaller plan','An invitation for two','Sam: “Saturday at three. I’ll send a table number, not a quiz-team membership form.”',
 B(({r})=>r.flags.includes('one_to_one')||r.flags.includes('small_group')?'You said you’d prefer something one-to-one. Would coffee work? No team, no quiz, no surprise group introduction.':'Would you fancy coffee this weekend? I promise not to turn it into an impromptu bike inspection.',
 C('Yes. Just the two of us sounds good.','Great. That was the idea.',1,1),C('Coffee as friends would be nice.','Friendly coffee it is.',1,0,'friends','friends'),C('I’d like to, but I’m still a little wary after the joke.','I understand. I can keep the afternoon simple.',1),C('I’m interested. Let’s call it a date.','I’d like that.',0,1,'dating'),C('Only if your friends won’t be involved.','They won’t be there. They will still exist.')),
 B('There’s a ride in the morning. I’d get back, shower, then meet you at three. Is the corner café okay?',
 C('Works for me.','Excellent. A plan with a sensible amount of coffee.',1),C('Could we do half three so you aren’t rushing?','That would actually help. Thanks.',1,0,'later_meet'),C('I like that you’re keeping your morning plan.','Good. I’d hate cancelling on people for a first date.',1),C('I’d have enjoyed hearing about the ride afterwards.','You will. Probably with exaggerated hills.',0,1),C('Skip the ride and spend the whole day with me.','I’m not cancelling a plan I already made. We can have the afternoon.',-2)),
 B('I’m still getting to know people. I don’t want one coffee to imply we’ve agreed to anything exclusive.',
 C('Same here. We’d talk about that if we wanted it.','Exactly.',1,0,'open'),C('I tend to focus on one person, but that’s my choice.','Okay. I appreciate you not making it an unspoken rule for me.',1),C('I’m only looking for friendship with you.','Thanks for being clear.',1,0,'friends','friends'),C('I’d be interested in that eventually, if things go well.','Maybe me too. Eventually.',0,1),C('If you’re interested in me, why talk to anyone else?','Because we haven’t agreed otherwise. I don’t want assumptions doing the talking.',-2)),
 B('One practical warning: I’m occasionally loud when I laugh. The cat finds it unacceptable.',
 C('I’ll try not to upset the cat by being funny.','A considerate approach.',1),C('Good. I like people who enjoy themselves.','That’s reassuring.',1),C('I’m quieter, but that’s okay.','Different volumes are allowed.'),C('I’d like to find out what makes you laugh.','We’ll see how your material holds up.',0,1),C('I’ll see you there. No need for a warning label.','Fair. See you there.'))),
S('An afternoon off','The corner café','Sam glances outside. “I should rescue my bike from the rain. I’ve enjoyed this.”',
 B('“Sam. Hi.” She puts her helmet under the table. “I nearly forgot to bring normal shoes. A very polished first impression.”',
 C('Normal shoes are overrated.','“Tell that to a café floor when I’m wearing cycling ones.”',1),C('It’s good to meet you.','“You too.”',1),C('How was the ride?','“Cold, good, and less heroic than I’ll claim later.”',1),C('You look great.','“Thanks. The shower did most of the work.”',0,1),C('You seem different in person.','“More three-dimensional, for a start.”')),
 B('A friend walks past the window and waves. Sam waves back, then stays in her seat. “They can catch me later.”',
 C('You could say a quick hello if you wanted.','“I will later. I’m here with you.”',1),C('Thanks. I was hoping for time with just you.','“I said that’s what we’d do.”',1),C('You know everyone around here.','“Not everyone. Just an inconveniently visible few.”'),C('I like seeing you have a life here.','“It’s taken a while to build. I’m fond of it.”',0,1),C('Please don’t mention me to them.','“I won’t share personal details. But I may say I had coffee with someone.”')),
 B('She asks about your week, listens, and then starts to make a joke before stopping. “Actually. Are jokes welcome, or is this a just-listen bit?”',
 C('A joke would help.','“Good. I had quite a good one forming.”',1),C('Just listen for a minute, please.','“Of course.”',1,0,'listen'),C('Thanks for asking. A bit of both.','“I can attempt that balance.”',1),C('I noticed you remembered our conversation.','“I did. I’m not always elegant about it, but I heard you.”',1,1),C('You don’t have to check everything. Relax.','“Okay. I’m trying not to make the same mistake twice.”')),
 B('Outside, she unlocks her bike without incident. “I’d like to see you again. What do you think?”',
 C('Yes. Another date would be good.','“Good. We’ll pick something together.”',1,2,'second_date','romantic'),C('I’d like to keep it friendly.','“Okay. I’d still enjoy your company.”',1,0,'friends','friends'),C('I’m interested, but I want to take it slowly.','“Works for me.”',1,1,'unsure'),C('I don’t feel the romantic spark.','“Fair enough. Thanks for telling me.”',0,0,'end_romance','friends'),C('Only if you’re ready to stop seeing other people now.','“I’m not ready to agree to that after one coffee.”',-2)))
];
// Photos are authored moments, saved with the message that introduces them.
stories.alex[0].beats[2].photo='alex-books';
stories.alex[0].beats[2].text='This is my very ambitious evening. Book, tea, laundry I’m ignoring. What do you usually do when you finish work?';
stories.alex[0].beats[2].choices[3]=C('A book and a quiet room looks pretty good to me.','It is. Though I’ve read the same page three times while talking to you.',1);
stories.ben[0].beats[1].photo='ben-noodles';
stories.ben[0].beats[1].text='Photo from my last day off. Yes, takeaway. I manage the restaurant across the square. Being surrounded by food all day apparently doesn’t teach you to feed yourself.';
stories.morgan[0].beats[1].photo='morgan-chair';
stories.morgan[0].beats[1].text='Passed this on the way to the cinema. A tiny chair beside a tree. No explanation. I walked home afterwards too—the city feels different when most of the shops are shut.';
stories.morgan[0].beats[1].choices[2]=C('Who is that chair for?','I have no idea. I’m checking for developments next time I pass.',1);
stories.maya[0].beats[2].photo='maya-cupboard';
stories.maya[0].beats[2].text='My latest project is painting this cupboard. It currently looks worse than before I started. I’m told this is part of the process.';
stories.daniel[1].beats[0].photo='daniel-walk';
stories.daniel[1].beats[0].text='A bit of this morning’s walk. It was peaceful until that delivery van reversed beside me for an entire street. How’s your day?';
stories.sam[0].beats[2].photo='sam-cat';
stories.sam[0].beats[2].text='Outside work I ride with a few friends. Nothing heroic. We usually undo the exercise at a bakery. Assuming I can get my helmet back from this one.';
stories.sam[0].beats[2].choices[3]=C('That cat looks very sure the helmet belongs to them.','Everything in the flat belongs to the cat. I’m apparently renting.',1);
if(typeof module!=='undefined')module.exports=stories;root.BTF_STORIES=stories;
})(typeof window!=='undefined'?window:globalThis);
